/* option A: explicit max width and center */
.lede { max-width: 720px; margin-left: auto; margin-right: auto; }

/* option B: force full-bleed block and constrain internal text */
.lede { width: 100%; }
.lede > .inner { max-width: 720px; margin: 0 auto; }

/* pick one of these fixes depending on desired behaviour */
/* 1) Force the paragraph to use the full container width */
.shell .cta-inner > div p { width: 100%; }

/* 2) Avoid engine-sensitive wrapping at that space by allowing hyphenation/breaking */
.shell .cta-inner > div p { word-break: break-word; hyphens: auto; }

/* 3) Eliminate fractional layout by using an integer width on the parent */
.shell .cta-inner > div { width: 527px; }

/* Example: make width deterministic and center */
.your-selector {
  max-width: 640px;    /* choose the desired text column width */
  margin-left: auto;
  margin-right: auto;
}
/* Or ensure integer pixel result if you must use percentage */
.your-selector { width: 56.0%; /* pick a percentage that resolves to an integer px at your container width */ }

.filters, .filters .fgroup { line-height: 22.475px; }
/* or: */
.filters, .filters .fgroup { line-height: 1.55; }

.filters, .fgroup {
  /* Example: use an integer pixel line-height to avoid fractional differences */
  line-height: 22px;
}

/* Or fix the ancestor height if appropriate */
.aside.filters {
  /* only if a fixed height works for your layout */
  height: 978px;
}

.filters, .layout, .fgroup {
  /* Option A: force a consistent px line-height to avoid per-engine fractional differences */
  line-height: 22.475px;
}
/* Or Option B: anchor the box so small ancestor differences won't move the child */
.fgroup {
  /* give the element an explicit height (if acceptable) */
  height: 91.14px;
}

.fgroup { line-height: 22px; }
/* or set a unit that rounds consistently across engines, e.g. */
.aside, .layout { line-height: 22px; }

.font-medium { /* option A: fix box size */ width: 110px; /* or flex-basis: 110px; */ }
/* or */
.font-medium { /* option B: make text measurement stable */ font-family: ui-monospace, Menlo, Consolas, monospace; }

/* Option A: fix the width so engines can't differ */ .font-medium { width: 94px; }
/* Option B: avoid content shrink-to-fit by using a flex item rule that establishes a basis */ .font-medium { flex: 0 0 auto; }
/* Option C: choose a platform-consistent font or a webfont with identical metrics */ .font-medium { font-family: 'YourWebFont', ui-monospace, monospace; }

form { width: 350.61px; /* or max-width: 350.61px; */ }
/* or avoid content-sized layout: */
form { justify-content: flex-start; }
/* or give the input/button fixed/flex-basis sizes so intrinsic measurements can't shift layout */

form input { box-sizing: border-box; width: 240px; padding: 0.75rem 1rem; border-width: 1px; }
/* Or, reset UA appearance entirely and then size: */
form input { appearance: none; -webkit-appearance: none; -moz-appearance: none; box-sizing: border-box; width: 240px; padding: 12px 16px; }

button.chip { font-family: inherit; }
/* or */
button.chip { font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }

table { table-layout: fixed; }
/* or */
col:nth-child(2) { width: 160px; }
/* or set explicit widths on the relevant th/td */

/* examples */
/* 1) Force the UL to a stable width so engines can't differ by subpixel rounding */
ul.your-selector { width: 186px; }

/* 2) Make flex sizing stable (if the issue comes from a flex child rounding) */
.your-flex-child { min-width: 0; /* allow proper shrinking inside flex */ }

/* 3) Make wrapping less sensitive to tiny width changes */
ul.your-selector { word-break: break-word; /* or overflow-wrap: anywhere; */ }

/* example: normalize the select so engines render the same box */
select#f-select-1 {
  appearance: none; /* opt out of native styling if you use a custom UI */
  height: 38px;      /* explicit height matching Chromium/Firefox */
  padding: 6px 8px; /* match design intent */
  box-sizing: border-box;
}
/* or normalize all native controls via a reset/normalize stylesheet */

.inline-flex.items-center.justify-center.gap-2 { width: 210.56px; }
/* or */
.flex-1.relative.rounded-2xl.border { width: 276.562px; }
/* or make the button fill its parent predictably: */
.inline-flex.items-center.justify-center.gap-2 { width: 100%; box-sizing: border-box; }

/* Option A: stable fixed algorithm */ table { table-layout: fixed; }
/* Option B: explicit column width */ colgroup { width: 668px; } colgroup col:nth-child(2) { width: 152px; }
/* Or set widths on the TH/TD involved */ thead th:nth-child(2), tbody td:nth-child(2) { width:152px; }
